CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, totp_secret text NOT NULL, role text NOT NULL CHECK(role IN('owner','editor','sales','analyst')), active boolean NOT NULL DEFAULT true, last_totp_step bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS content(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,kind text NOT NULL CHECK(kind IN('page','post','case')),draft jsonb NOT NULL,version integer NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','in_review','approved','published','scheduled')),published_revision uuid,approved_by uuid REFERENCES users(id),scheduled_at timestamptz,deleted_at timestamptz,deleted_by uuid REFERENCES users(id),deletion_reason text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),content_id uuid NOT NULL REFERENCES content(id) ON DELETE RESTRICT,body jsonb NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(content_id,id));
ALTER TABLE content ADD CONSTRAINT live_revision_belongs_to_content FOREIGN KEY(id,published_revision) REFERENCES revisions(content_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY,actor text NOT NULL,action text NOT NULL,object_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',previous_hash text NOT NULL,hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS consent(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,analytics boolean NOT NULL,advertising boolean NOT NULL,policy_version text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '180 days');
CREATE TABLE IF NOT EXISTS consent_history(id bigserial PRIMARY KEY,consent_id uuid NOT NULL REFERENCES consent(id),analytics boolean NOT NULL,advertising boolean NOT NULL,policy_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS acquisition(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),consent_id uuid NOT NULL REFERENCES consent(id),fields jsonb NOT NULL,route text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt text UNIQUE NOT NULL,event_id uuid UNIQUE NOT NULL,submission_key text UNIQUE NOT NULL,fingerprint text NOT NULL,encrypted_fields text NOT NULL,form_revision text NOT NULL,source text NOT NULL,stage text NOT NULL DEFAULT 'new' CHECK(stage IN('new','contacted','qualified','won','lost','spam')),version integer NOT NULL DEFAULT 1,consent_id uuid REFERENCES consent(id),acquisition_id uuid REFERENCES acquisition(id),assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lead_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL REFERENCES leads(id),actor_id uuid REFERENCES users(id),type text NOT NULL,encrypted_note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid UNIQUE NOT NULL,type text NOT NULL,aggregate_id uuid NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','completed','retry','blocked','dead_letter')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_due ON outbox(status,available_at);
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid REFERENCES leads(id),title text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','done')),execution_key text UNIQUE NOT NULL,due_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY,consent_id uuid NOT NULL REFERENCES consent(id),name text NOT NULL,route text NOT NULL,action_id text,occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value jsonb NOT NULL,version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),definition jsonb NOT NULL,url text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),definition jsonb NOT NULL,active boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workflow_id uuid NOT NULL REFERENCES workflows(id),lead_id uuid NOT NULL REFERENCES leads(id),definition jsonb NOT NULL,next_node integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'running',due_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workflow_id,lead_id));
CREATE TABLE IF NOT EXISTS media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),path text UNIQUE NOT NULL,alt text NOT NULL,rights text NOT NULL,checksum text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chats(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day');
CREATE TABLE IF NOT EXISTS chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),chat_id uuid NOT NULL REFERENCES chats(id),client_id uuid NOT NULL,topic text NOT NULL,answer text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(chat_id,client_id));
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS privacy_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),encrypted_contact text NOT NULL,kind text NOT NULL,status text NOT NULL DEFAULT 'verification_required',created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION protect_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable source or audit record: manual governed recovery required'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON audit FOR EACH STATEMENT EXECUTE FUNCTION protect_history();
CREATE TRIGGER revision_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON revisions FOR EACH STATEMENT EXECUTE FUNCTION protect_history();
CREATE TRIGGER content_no_delete BEFORE DELETE OR TRUNCATE ON content FOR EACH STATEMENT EXECUTE FUNCTION protect_history();
